class TrafficLight
    private define state as integer;

    method constructor()
        this.state <- 0;
    endMethod

    public method Next()
        if this.state = 2 then
            this.state <- 0;
        else
            this.state <- this.state + 1;
        endIf
    endMethod

    public method State() as integer
        return this.state;
    endMethod
endClass

algorithm RunTrafficLight
    define times as integer;
    define i as integer;
    define light as TrafficLight;
    read times;
    light <- new TrafficLight();
    for i <- 1 to times step 1 do
        light.Next();
    endFor
    write light.State();
endAlgorithm
